css:
@import url('https://fonts.googleapis.com/css2?family=Courier+Prime:wght@400;700&display=swap');

:root {
  --primary: #FF00FF;
  --bg-main: #000000;
  --card-bg: #000000;
  --text-main: #00FF00;
  --text-muted: #33FF33;
  --border-color: #00FF00;
  --radius: 0px;
  --font-main: 'Courier Prime', monospace;
  --shadow: 8px 8px 0px #FF00FF;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-main);
  background: var(--bg-main);
  color: var(--text-main);
  line-height: 1.4;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  text-transform: uppercase;
}

a {
  text-decoration: underline;
  color: var(--primary);
}

.site-header {
  background: var(--bg-main);
  border-bottom: 4px solid var(--border-color);
  padding: 20px;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-container {
  max-width: 1000px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 2rem;
  font-weight: 700;
  color: var(--primary);
  border: 2px solid var(--primary);
  padding: 5px 10px;
}

.layout-container {
  max-width: 1000px;
  margin: 50px auto;
  padding: 0 20px;
  width: 100%;
  flex-grow: 1;
}

.post-list {
  display: flex;
  flex-direction: column;
  gap: 30px;
}

.post-item {
  background: var(--card-bg);
  padding: 25px;
  border: 3px solid var(--border-color);
  box-shadow: var(--shadow);
  transition: 0.1s;
}

.post-item:hover {
  background: #111;
  transform: translate(-4px, -4px);
}

.post-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 15px;
  color: #fff;
}

.post-meta {
  display: flex;
  gap: 20px;
  font-size: 0.75rem;
  color: var(--text-muted);
  border-top: 2px dashed var(--border-color);
  padding-top: 15px;
  margin-top: 15px;
}

.message-block {
  background: var(--card-bg);
  border: 3px solid var(--border-color);
  margin-bottom: 40px;
  display: flex;
  flex-direction: column;
}

@media(min-width: 600px) {
  .message-block {
    flex-direction: row;
  }
}

.user-panel {
  background: #0d0d0d;
  padding: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  border-bottom: 3px solid var(--border-color);
  width: 100%;
}

@media(min-width: 600px) {
  .user-panel {
    width: 200px;
    border-bottom: none;
    border-right: 3px solid var(--border-color);
  }
}

.user-panel img {
  width: 80px;
  height: 80px;
  border: 2px solid var(--primary);
  border-radius: 0px;
  margin-bottom: 15px;
}

.user-name-side {
  font-weight: 700;
  font-size: 0.9rem;
}

.message-content {
  padding: 25px;
  flex-grow: 1;
}

.message-header {
  display: flex;
  justify-content: space-between;
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-bottom: 20px;
  border-bottom: 1px dotted var(--border-color);
  padding-bottom: 10px;
}

.message-text {
  font-size: 1.1rem;
}

.badge {
  background: var(--primary);
  color: #000;
  padding: 2px 6px;
  font-size: 0.7rem;
  border-radius: 0px;
  font-weight: bold;
  display: inline-block;
  margin-top: 15px;
}

.pagination {
  display: flex;
  justify-content: center;
  gap: 15px;
  margin-top: 50px;
}

.page-link {
  padding: 10px 20px;
  background: transparent;
  border: 2px solid var(--border-color);
  color: var(--text-main);
  font-weight: 700;
}

.page-link.active {
  background: var(--border-color);
  color: #000;
}

.site-footer {
  background: #0a0a0a;
  padding: 40px;
  text-align: center;
  color: var(--text-muted);
  border-top: 4px solid var(--border-color);
  margin-top: auto;
}
